import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { Row, Col, Card, Button, Input, Modal, Form, Select, Spin, message } from 'antd';
import { PlusOutlined } from '@ant-design/icons';
import KanbanService from 'classes/KanbanService';
import KanbanCard from 'components/KanbanCard';

const COLUMNS = [
  { key: 'todo', title: 'To Do' },
  { key: 'in_progress', title: 'In Progress' },
  { key: 'done', title: 'Done' },
];

export default function KanbanPage() {
  const service = useMemo(() => new KanbanService('kanban_task'), []);
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dragId, setDragId] = useState(null);
  const [open, setOpen] = useState(false);
  const [form] = Form.useForm();

  const load = useCallback(() => {
    setLoading(true);
    service.listTasks()
      .then(setTasks)
      .catch(() => setTasks([]))
      .finally(() => setLoading(false));
  }, [service]);

  useEffect(() => { load(); }, [load]);

  const onDrop = async (status) => {
    const id = dragId;
    setDragId(null);
    if (!id) return;
    const task = tasks.find((t) => t.id === id);
    if (!task || task.status === status) return;
    setTasks((prev) => prev.map((t) => (t.id === id ? { ...t, status } : t)));
    try {
      await service.moveTask(id, status);
    } catch (e) {
      message.error('Failed to move task');
      load();
    }
  };

  const onDelete = async (task) => {
    setTasks((prev) => prev.filter((t) => t.id !== task.id));
    try {
      await service.deleteTask(task.id);
    } catch (e) {
      message.error('Failed to delete task');
      load();
    }
  };

  const onCreate = async () => {
    const values = await form.validateFields();
    await service.createTask(values);
    setOpen(false);
    form.resetFields();
    load();
  };

  if (loading) {
    return <div style={{ padding: 40, textAlign: 'center' }}><Spin size="large" /></div>;
  }

  return (
    <div style={{ padding: 24 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <h2 style={{ margin: 0 }}>Kanban Board</h2>
        <Button type="primary" icon={<PlusOutlined />} onClick={() => setOpen(true)}>New Task</Button>
      </div>

      <Row gutter={16}>
        {COLUMNS.map((col) => {
          const colTasks = tasks.filter((t) => (t.status || 'todo') === col.key);
          return (
            <Col key={col.key} xs={24} sm={8}>
              <Card
                title={col.title + ' (' + colTasks.length + ')'}
                styles={{ body: { minHeight: 420, background: 'rgba(127,127,127,0.06)' } }}
                onDragOver={(e) => e.preventDefault()}
                onDrop={() => onDrop(col.key)}
              >
                {colTasks.map((task) => (
                  <div key={task.id} draggable onDragStart={() => setDragId(task.id)}>
                    <KanbanCard task={task} onDelete={onDelete} />
                  </div>
                ))}
                {colTasks.length === 0 ? (
                  <div style={{ textAlign: 'center', color: '#bbb', padding: '24px 0' }}>Drop tasks here</div>
                ) : null}
              </Card>
            </Col>
          );
        })}
      </Row>

      <Modal title="New Task" open={open} onOk={onCreate} onCancel={() => setOpen(false)} destroyOnClose>
        <Form form={form} layout="vertical">
          <Form.Item name="title" label="Title" rules={[{ required: true, message: 'Title is required' }]}>
            <Input placeholder="Task title" />
          </Form.Item>
          <Form.Item name="description" label="Description">
            <Input.TextArea rows={3} />
          </Form.Item>
          <Form.Item name="priority" label="Priority" initialValue="medium">
            <Select
              options={[
                { value: 'low', label: 'Low' },
                { value: 'medium', label: 'Medium' },
                { value: 'high', label: 'High' },
              ]}
            />
          </Form.Item>
          <Form.Item name="status" label="Status" initialValue="todo">
            <Select options={COLUMNS.map((c) => ({ value: c.key, label: c.title }))} />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
}
